    public void offerData(long cursor, String frameText) {
        throw new UnsupportedOperationException();
    }

    /** 立即发送控制帧（Service/Action/订阅应答），不进入数据队列、不参与丢弃。 */
    public void sendControl(Map<String, Object> frame) {
        throw new UnsupportedOperationException();
    }

    /** ACK 到指定游标：清除已发送未确认记录；返回此前已确认游标。 */
    public long ack(long cursor) {
        throw new UnsupportedOperationException();
    }

    /** 关闭底层连接，停止所有投递。 */
    public void close() {
        throw new UnsupportedOperationException();
    }

    public boolean isOpen() {
        throw new UnsupportedOperationException();
    }

    /** 当前未确认（在队或已发）数据消息数，测试用。 */
    public int unackedCount() {
        throw new UnsupportedOperationException();
    }
}

