package com.example.starter.rosbridge.ws;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.socket.TextMessage;
import org.springframework.web.socket.WebSocketSession;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link ClientSession} 单元测试：慢消费者丢弃最旧未确认消息、
 * RESUME_GAP 区间、ACK 清除与不影响其他客户端（通过独立会话验证）。
 */
class ClientSessionTest {

    private ObjectMapper mapper;
    private ManualScheduledExecutor scheduler;
    private List<String> sentA;
    private List<String> sentB;
    private ClientSession sessionA;
    private ClientSession sessionB;

    @BeforeEach
    void setUp() {
        mapper = new ObjectMapper();
        scheduler = new ManualScheduledExecutor();
        sentA = new CopyOnWriteArrayList<>();
        sentB = new CopyOnWriteArrayList<>();
        sessionA = new SessionBuilder("c1").capacity(3).build();
        sessionB = new SessionBuilder("c2").capacity(3).build();
    }

    @Test
    void queueFullDropsOldestUnackedAndEmitsResumeGap() throws Exception {
        // 填满 3 条队列：offer 会立即尝试 flush，但本测试先不触发周期任务，
        // sendMessage 同步成功后队列即被刷空。因此通过“写入阻塞探针”保持堆积：
        // 改用直接验证：连续 offer 4 条且关闭 flush 影响——构造不自动 flush 的会话。
        ClientSession noFlush = newSessionWithManualFlushOnly("c-slow", 3, sentA);
        offer(noFlush, 1);
        offer(noFlush, 2);
        offer(noFlush, 3);
        assertEquals(3, noFlush.unackedCount());

        // 第 4 条使队列满：丢弃最旧游标 1，并在队首生成 RESUME_GAP[1,1]。
        offer(noFlush, 4);
        scheduler.runPeriodicTasks();

        List<JsonNode> frames = parseAll(sentA);
        // 第一帧必须是 RESUME_GAP，范围闭区间 [1,1]。
        assertEquals("RESUME_GAP", frames.get(0).get("op").asText());
        assertEquals(1, frames.get(0).get("fromCursor").asLong());
        assertEquals(1, frames.get(0).get("toCursor").asLong());
        assertEquals(1, frames.get(0).get("dropped").asInt());
        // 随后只投递保留下来的游标 2、3、4，游标 1 不再出现。
        List<Long> cursors = frames.stream().filter(f -> "PUBLISH".equals(f.get("op").asText()))
                .map(f -> f.get("cursor").asLong()).toList();
        assertEquals(List.of(2L, 3L, 4L), cursors);
    }

    @Test
    void consecutiveOverflowsMergeIntoSingleGapRange() throws Exception {
        ClientSession noFlush = newSessionWithManualFlushOnly("c-slow2", 2, sentA);
        offer(noFlush, 1);
        offer(noFlush, 2);
        offer(noFlush, 3); // 丢弃 1
        offer(noFlush, 4); // 丢弃 2
        scheduler.runPeriodicTasks();

        List<JsonNode> gapFrames = parseAll(sentA).stream()
                .filter(f -> "RESUME_GAP".equals(f.get("op").asText())).toList();
        assertEquals(1, gapFrames.size(), "连续溢出应合并为单个 RESUME_GAP");
        assertEquals(1, gapFrames.get(0).get("fromCursor").asLong());
        assertEquals(2, gapFrames.get(0).get("toCursor").asLong());
        assertEquals(2, gapFrames.get(0).get("dropped").asInt());
    }

    @Test
    void ackRemovesConfirmedMessagesAndPreventsRedelivery() throws Exception {
        ClientSession noFlush = newSessionWithManualFlushOnly("c-ack", 10, sentA);
        offer(noFlush, 1);
        offer(noFlush, 2);
        long before = noFlush.ack(2);
        assertEquals(0, before);
        assertEquals(0, noFlush.unackedCount(), "ACK 后已确认消息应移出队列");

        // 游标不大于确认水位的消息不得再次入队。
        offer(noFlush, 1);
        offer(noFlush, 2);
        offer(noFlush, 3);
        scheduler.runPeriodicTasks();
        List<Long> cursors = parseAll(sentA).stream()
                .filter(f -> "PUBLISH".equals(f.get("op").asText()))
                .map(f -> f.get("cursor").asLong()).toList();
        assertEquals(List.of(3L), cursors, "不得重复投递已确认的游标 1、2");
    }

    @Test
    void slowConsumerDoesNotAffectOtherClient() throws Exception {
        // 客户端 A 队列极小并持续溢出；客户端 B 独立队列应完整收到全部消息。
        ClientSession slow = newSessionWithManualFlushOnly("c-A", 2, sentA);
        offer(slow, 1);
        offer(slow, 2);
        offer(slow, 3); // A 丢弃 1

        offer(sessionB, 10);
        offer(sessionB, 11);
        offer(sessionB, 12);
        scheduler.runPeriodicTasks();

        List<Long> aCursors = parseAll(sentA).stream()
                .filter(f -> "PUBLISH".equals(f.get("op").asText()))
                .map(f -> f.get("cursor").asLong()).toList();
        assertEquals(List.of(2L, 3L), aCursors, "慢客户端 A 只保留最新 2 条");

        List<Long> bCursors = parseAll(sentB).stream()
                .map(f -> f.get("cursor").asLong()).toList();
        assertEquals(List.of(10L, 11L, 12L), bCursors, "客户端 B 不受 A 溢出影响");
        assertTrue(sentB.stream().noneMatch(t -> t.contains("RESUME_GAP")),
                "客户端 B 不应收到任何 GAP 帧");
    }

    @Test
    void controlFrameIsSentImmediatelyAndNotDropped() {
        ClientSession noFlush = newSessionWithManualFlushOnly("c-ctrl", 1, sentA);
        offer(noFlush, 1);
        offer(noFlush, 2); // 触发溢出
        sessionA.sendControl(Map.of("op", "SERVICE_RESPONSE", "requestId", "r1"));
        // c-ctrl 会话发控制帧
        ClientSession c = newSessionWithManualFlushOnly("c-ctrl2", 1, sentB);
        offer(c, 1);
        offer(c, 2);
        c.sendControl(Map.of("op", "SUBSCRIBED", "topic", "/t"));
        JsonNode last = parseAll(sentB).get(0);
        // 控制帧最先被即时发出（在周期 flush 之前）。
        assertEquals("SUBSCRIBED", last.get("op").asText());
        assertFalse(c.isOpen() == false);
    }

    // ---- 辅助 ----

    private void offer(ClientSession session, long cursor) {
        try {
            Map<String, Object> frame = Map.of(
                    "op", "PUBLISH", "topic", "/t", "type", "std_msgs/msg/String",
                    "cursor", cursor, "msg", Map.of("data", "m" + cursor));
            session.offerData(cursor, mapper.writeValueAsString(frame));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private ClientSession newSessionWithManualFlushOnly(String clientId, int capacity,
                                                        List<String> sink) {
        WebSocketSession ws = fakeSession(sink);
        return new ClientSession(clientId, ws, 0, capacity, 0L, mapper, scheduler);
    }

    private List<JsonNode> parseAll(List<String> raw) {
        List<JsonNode> nodes = new ArrayList<>();
        for (String text : raw) {
            try {
                nodes.add(mapper.readTree(text));
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        return nodes;
    }

    @SuppressWarnings("unchecked")
    private WebSocketSession fakeSession(List<String> sink) {
        return (WebSocketSession) Proxy.newProxyInstance(
                WebSocketSession.class.getClassLoader(),
                new Class<?>[]{WebSocketSession.class},
                (proxy, method, args) -> {
                    if ("sendMessage".equals(method.getName()) && args[0] instanceof TextMessage tm) {
                        sink.add(tm.getPayload());
                        return null;
                    }
                    if ("isOpen".equals(method.getName())) {
                        return true;
                    }
                    if ("close".equals(method.getName())) {
                        return null;
                    }
                    return defaultValue(method.getReturnType());
                });
    }

    private static Object defaultValue(Class<?> type) {
        if (type == boolean.class) {
            return false;
        }
        if (type == int.class) {
            return 0;
        }
        if (type == long.class) {
            return 0L;
        }
        return null;
    }

    private final class SessionBuilder {
        private final String clientId;
        private int capacity = 64;
        private List<String> sink;

        private SessionBuilder(String clientId) {
            this.clientId = clientId;
        }

        private SessionBuilder capacity(int capacity) {
            this.capacity = capacity;
            return this;
        }

        private ClientSession build() {
            this.sink = clientId.equals("c1") ? sentA : sentB;
            return new ClientSession(clientId, fakeSession(sink), 0, capacity, 0L,
                    mapper, scheduler);
        }
    }
}

