    public synchronized void tick(long deltaMs) {
        virtualNowMs += deltaMs;
        List<Task> due = new ArrayList<>();
        for (Task t : delayedTasks) {
            if (!t.future.cancelled.get() && t.deadlineMs <= virtualNowMs) {
                due.add(t);
            }
