package com.example.starter.rosbridge.topic;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

/**
 * {@link QosNormalizer} 单元测试：字段顺序不同的等价 QoS 必须规范化为同一摘要。
 */
class QosNormalizerTest {

    private final QosNormalizer normalizer = new QosNormalizer(new ObjectMapper());

    @Test
    void keyOrderDoesNotAffectCanonicalHash() {
        QosNormalizer.NormalizedQos a = normalizer.normalize(new ObjectMapper()
                .readTree("{\"depth\":10,\"reliability\":\"reliable\"}")
                .deepCopy());
        QosNormalizer.NormalizedQos b;
        try {
            b = normalizer.normalize(new ObjectMapper()
                    .readTree("{\"reliability\":\"reliable\",\"depth\":10}"));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        assertEquals(a.hash(), b.hash(), "键顺序不同的等价 QoS 摘要必须一致");
        assertEquals(a.canonicalJson(), b.canonicalJson());
    }

    @Test
    void differentQosValuesHaveDifferentHash() throws Exception {
        QosNormalizer.NormalizedQos reliable = normalizer.normalize(
                new ObjectMapper().readTree("{\"depth\":10}"));
        QosNormalizer.NormalizedQos bestEffort = normalizer.normalize(
                new ObjectMapper().readTree("{\"depth\":1}"));
        assertNotEquals(reliable.hash(), bestEffort.hash());
    }

    @Test
    void nullQosNormalizesToEmptyObject() {
        QosNormalizer.NormalizedQos q = normalizer.normalize(null);
        assertEquals("{}", q.canonicalJson());
    }
}

